11: // Bob Shell 2.x transmite la respuesta en eventos "message" del asistente y el
12: // evento "result" trae solo estado y costos; last_message queda como respaldo.
13: export function parseBobJson(event, streamed = '') {
14:   if (event.type !== 'result' || event.status !== 'success') throw new Error('Bob no completó el análisis.');
15:   const raw = String(event.last_message || streamed || '');
16:   const start = raw.indexOf('{'), end = raw.lastIndexOf('}');
17:   if (start < 0 || end < start) throw new Error('Bob respondió sin JSON.');
18:   return JSON.parse(raw.slice(start, end + 1));
19: }
