203: // Pages are split into batches and each batch is a separate Bob task. Batches
204: // run concurrently (bounded), so more pages fit in about the time of a single
205: // smaller call, and one failed batch does not discard the others.
206: export function lotes(documents, tamano) {
207:   const result = [];
208:   for (let i = 0; i < documents.length; i += tamano) result.push(documents.slice(i, i + tamano));
