212: async function enParalelo(items, limite, fn) {
213:   const results = new Array(items.length);
214:   let next = 0;
215:   const worker = async () => {
216:     while (next < items.length) {
217:       const i = next++;
218:       try { results[i] = { ok: true, value: await fn(items[i], i) }; }
219:       catch (error) { results[i] = { ok: false, error }; }
220:     }
221:   };
222:   await Promise.all(Array.from({ length: Math.min(limite, items.length) }, worker));
223:   return results;
